def solve(grid):
    if not grid or not grid[0]:
        return grid

    # Create a copy of the grid
    result = [row[:] for row in grid]
    rows = len(result)
    cols = len(result[0]) if rows > 0 else 0

    # The fill value is the first element
    fill_val = result[0][0]

    # Extract path sequence from first row
    # Values at positions 3, 7, 11, ... (every 4 starting from 3)
    path_values = [fill_val]
    for c in range(3, cols, 4):
        if result[0][c] != 0:
            path_values.append(result[0][c])

    # Find all box centers (non-zero, non-5 values in the grid)
    value_positions = {}
    for r in range(rows):
        for c in range(cols):
            val = result[r][c]
            if val != 0 and val != 5:
                if val not in value_positions:
                    value_positions[val] = []
                value_positions[val].append((r, c))

    # Helper to get position of a value
    def get_pos(val):
        if val in value_positions and value_positions[val]:
            # Return the first occurrence (should be unique for path values)
            return value_positions[val][0]
        return None

    # Draw the path between consecutive values
    for i in range(len(path_values) - 1):
        start_val = path_values[i]
        end_val = path_values[i + 1]

        start_pos = get_pos(start_val)
        end_pos = get_pos(end_val)

        if start_pos is None or end_pos is None:
            continue

        r1, c1 = start_pos
        r2, c2 = end_pos

        # Check if this is the last segment
        is_last_segment = (i == len(path_values) - 2)

        if is_last_segment:
            # Stop at the boundary of the target box
            # Determine direction and stop one cell before the center
            if r1 == r2:
                # Horizontal movement
                if c2 > c1:
                    c2 = c2 - 1
                else:
                    c2 = c2 + 1
            elif c1 == c2:
                # Vertical movement
                if r2 > r1:
                    r2 = r2 - 1
                else:
                    r2 = r2 + 1
            else:
                # Manhattan: move horizontal then vertical
                # Adjust the target for the last step
                # We need to stop adjacent to the final center
                # The path goes (r1,c1) -> (r1,c2) -> (r2,c2)
                # So stop at (r1, c2_adj) or (r2_adj, c2)
                # Actually, stop one step before reaching (r2,c2) along the path
                pass  # Will be handled by drawing logic below

        # Draw horizontal then vertical (Manhattan path)
        # Horizontal segment
        if c1 != c2:
            step = 1 if c2 > c1 else -1
            c_end = c2
            if is_last_segment and r1 == r2:
                # Pure horizontal last segment
                c_target = c2
            for c in range(c1, c2 + step, step):
                if is_last_segment:
                    # Check if we reached the cell before target
                    if r1 == r2 and c == c2:
                        break
                    if c == c2 and r1 != r2:
                        # This is the turn point, fill it and continue to vertical
                        pass
                result[r1][c] = fill_val

        # Vertical segment
        if r1 != r2:
            step = 1 if r2 > r1 else -1
            r_start = r1
            # If we did horizontal, start from r1 (already filled) or r1+1?
            # Actually fill from r1 to r2 inclusive (except last if is_last_segment)
            r_end = r2
            if is_last_segment:
                # Stop one before r2
                r_end = r2 - step

            for r in range(r_start, r_end + step, step):
                if r == r_start and c1 != c2:
                    # Already filled at the corner by horizontal
                    continue
                result[r][c2] = fill_val

    return result
